<script lang="ts">
 import {useLocale,text} from '$lib/shared/presentation/locale';
 import {copy,noticeText,failureCode} from '$lib/shared/presentation/copy';
 const {locale,change:changeLanguage}=useLocale();
 import {publicationStates,preparationLabel} from './messages';
 const stateNames=$derived(publicationStates($locale));
 const pageStates=$derived<Record<string,string>>({...stateNames,ready:text($locale,'Дайын','Готово')});
 import { onMount, tick } from 'svelte';
 import {beforeNavigate} from '$app/navigation';
 import {page as routePage} from '$app/stores';
 import {workspaceLocation,workspaceSteps,projectListReturn} from '../domain/workspace-context';
 import type {UploadSource} from '../application/publishing';
 import type { Account } from '$lib/features/identity/domain/account';
 import { replacePage, UploadQueue, type PublishingGateway, type Revision, type ChapterChoice,type StudioProject } from '../application/publishing';
 import {movePage} from '../domain/page-order';
 import {processingSummary,submissionObstacles,type SubmissionObstacle} from '../domain/preflight';
 import { canEdit, canSubmit } from '../domain/revision';
 let { user, projectId, gateway }: { user: Account | null; projectId: string; gateway: PublishingGateway } = $props();
 function previewHref(){if(!active)return '#';const returnTo=workspaceLocation(projectId,active.id,activeStep,previewPosition);return '/read/'+encodeURIComponent(active.releaseId)+'?preview='+encodeURIComponent(active.id)+'&returnTo='+encodeURIComponent(returnTo);}
 let previewPosition=$state(0);
 let discardDialog:HTMLDialogElement|undefined;
 let activeStep=$state('draft-pages');
 let choosingChapter=$state(true);
 let chapterChoice=$state<HTMLDetailsElement>();
 async function showChapterChoice(){
  choosingChapter=true;await tick();
  const summary=chapterChoice?.querySelector('summary');
  summary?.focus({preventScroll:true});summary?.scrollIntoView({block:'start'});
 }
 const stepIDs=['draft-pages','draft-details','draft-preview'];
 const stepNumber=$derived(stepIDs.indexOf(activeStep)+1);
 async function showStep(id:string){
  activeStep=id;
  await tick();
  const heading=document.querySelector<HTMLElement>('#'+id+' h3');
  heading?.focus({preventScroll:true});
  heading?.scrollIntoView({block:'start'});
 }
 async function saveAndReview(){await saveAttribution();await showStep('draft-preview');}

 let moreChapters=$state(false),moreRevisions=$state(false),project=$state<StudioProject|null>(null),newChapter=$state(false),chapterLabel=$state(''),chapterVolume=$state(''),chapterName=$state(''),chapterOrder=$state('');
 const editor=$derived(project?.approved&&project.status==='active'&&(project.role==='owner'||project.role==='editor'));
 function clearChapterInputs(){chapterLabel='';chapterVolume='';chapterName='';chapterOrder='';}
 async function openDraft(){
  if(!project)return;
  let selected=chapterId;
  if(newChapter){
   selected=await gateway.createChapter(projectId,{label:chapterLabel,volume:chapterVolume,name:chapterName,order:chapterOrder?Number(chapterOrder):0});
   chapterId=selected;newChapter=false;clearChapterInputs();
  }
  active=await gateway.create(projectId,selected);
  chapterId=selected;clearChapterInputs();choosingChapter=false;activeStep='draft-pages';await reload();
 }
 async function discardDraft(){if(!active)return;const id=active.id,version=active.version;try{await gateway.discard(id,version);}catch(failure){if(failureCode(failure)==='conflict'){try{active=await gateway.revision(id);await reload();}catch{active=null;await reload();}discardDialog?.close();}throw failure;}discardDialog?.close();if(active?.id===id)active=null;order=null;pendingSources=[];await reload();notice='draft_discarded';}
 async function loadMoreChapters(){const next=await gateway.chapters(projectId,chapters.length);chapters=[...chapters,...next];moreChapters=next.length===100;}
 async function loadMoreRevisions(){const next=await gateway.revisions(projectId,revisions.length);revisions=[...revisions,...next];moreRevisions=next.length===100;}
 let chapters = $state<ChapterChoice[]>([]), revisions = $state<Revision[]>([]), active = $state<Revision | null>(null), chapterId = $state('');
 const revisionGroups=$derived.by(()=>{
  const groups=new Map<string,{id:string;label:string;name:string;revisions:Revision[]}>();
  for(const revision of revisions){
   let group=groups.get(revision.chapterId);
   if(!group){const chapter=chapters.find(item=>item.id===revision.chapterId);group={id:revision.chapterId,label:chapter?.label||revision.chapterLabel,name:chapter?.name||'',revisions:[]};groups.set(revision.chapterId,group);}
   group.revisions.push(revision);
  }
  return [...groups.values()];
 });
 async function openRevision(id:string){const next=await gateway.revision(id);if(next.projectId!==projectId)throw new Error('revision_unavailable');active=next;chapterId=next.chapterId;choosingChapter=false;}
 let busy = $state(false), uploading = $state(false), progress = $state(0), progressText = $state(''), error = $state(''), notice = $state(''),shareText=$state(''),shareCopied=$state(false);
 let order=$state<string[]|null>(null),orderVersion=$state(0);
 const orderedPages=$derived(active?(order||active.pages.map(page=>page.id)).map(id=>active!.pages.find(page=>page.id===id)!).filter(Boolean):[]);
 function stageMove(id:string,position:number){if(active){if(order===null)orderVersion=active.version;order=movePage(order||active.pages.map(page=>page.id),id,position);}}
 let preparationMethod=$state('unspecified'),humanReviewed=$state(false),attributionVersion=$state(0);
 let source=$state(''),credits=$state(''),confirmed=$state(false),attributionID=$state('');
 const attributionDirty=$derived(!!active&&(source!==(active.source||'')||credits!==(active.credits||'')||confirmed!==(active.rightsConfirmed===true)||preparationMethod!==(active.preparationMethod||'unspecified')||humanReviewed!==(active.humanReviewed===true)));
 $effect(()=>{if(active&&active.id!==attributionID){attributionID=active.id;order=null;replacementCapacity=false;shareText='';shareCopied=false;source=active.source||'';credits=active.credits||'';confirmed=active.rightsConfirmed===true;preparationMethod=active.preparationMethod||'unspecified';humanReviewed=active.humanReviewed===true;attributionVersion=active.version;}});
 let pendingSources=$state<UploadSource[]>([]);
 const processing=$derived(processingSummary(active?.pages||[]));
 const obstacles=$derived(active?submissionObstacles(active,{editor:!!editor,uploading,pending:pendingSources.length>0,orderDirty:order!==null,detailsDirty:attributionDirty}):[]);
 function obstacleLabel(reason:SubmissionObstacle){const labels:Record<SubmissionObstacle,[string,string]>={permission:['Редактор не иесі жібере алады','Отправить может редактор или владелец'],transfer:['Файлдарды жүктеуді аяқта','Заверши передачу файлов'],pages:['Беттерді қос','Добавь страницы'],failed:['Қате беттерді түзет','Исправь страницы с ошибками'],processing:['Беттердің өңделуін күт немесе күйін жаңарт','Дождись обработки страниц или обнови состояние'],order:['Беттердің ретін сақта','Сохрани порядок страниц'],details:['Дереккөзді, кредиттерді және құқықтарды тексеріп, сақта','Проверь и сохрани источник, кредиты и подтверждение прав']};return text($locale,...labels[reason]);}
 async function focusPage(id:string){await showStep('draft-pages');await tick();const row=document.getElementById('studio-page-'+id);row?.focus({preventScroll:true});row?.scrollIntoView({block:'center'});}
 let pageOverview=$state(false);
 let queue: UploadQueue | null = null;
 let refreshSequence=0;
 let replacementCapacity=$state(false);

 const chapterDirty=$derived(!!(chapterLabel||chapterVolume||chapterName||chapterOrder));
 const unsaved=$derived(chapterDirty||order!==null||attributionDirty||uploading||pendingSources.length>0);
 beforeNavigate(navigation=>{if(unsaved&&navigation.willUnload){navigation.cancel();return;}if(unsaved&&!window.confirm(text($locale,'Сақталмаған өзгерістер бар. Шығу керек пе?','Есть несохранённые изменения. Уйти?')))navigation.cancel();});
 async function run(action: () => Promise<void>) { if (busy) return; busy = true; error = ''; notice = ''; try { await action(); } catch (failure) { error = failureCode(failure); } finally { busy = false; } }
 async function reload() { project=await gateway.project(projectId);[chapters,revisions] = await Promise.all([gateway.chapters(projectId),gateway.revisions(projectId)]);moreChapters=chapters.length===100;moreRevisions=revisions.length===100;if(!chapters.length)newChapter=true;if(!active&&revisions.length){const chosen=revisions.find(revision=>canEdit(revision.state))||revisions[0];active=await gateway.revision(chosen.id);chapterId=active.chapterId;choosingChapter=false;} }
 function syncAttribution(revision:Revision){source=revision.source||'';credits=revision.credits||'';confirmed=revision.rightsConfirmed===true;preparationMethod=revision.preparationMethod||'unspecified';humanReviewed=revision.humanReviewed===true;attributionVersion=revision.version;}
 async function refresh() { if(active){
  const previous=active;const sequence=++refreshSequence;const next=await gateway.revision(active.id);
  if(active?.id!==previous.id||sequence!==refreshSequence||next.version<active.version)return;
  if(!attributionDirty)syncAttribution(next);
  else if(next.source===previous.source&&next.credits===previous.credits&&next.rightsConfirmed===previous.rightsConfirmed&&next.preparationMethod===previous.preparationMethod&&next.humanReviewed===previous.humanReviewed)attributionVersion=next.version;
  active=next;const current=active;revisions=revisions.map(revision=>revision.id===current.id?current:revision);if(active.state==='ready'&&notice==='upload_received')notice='';
 } }
 onMount(() => {
  if (user) void run(async()=>{
   await reload();
   const requested=$routePage.url.searchParams.get('revision');
   if(requested){try{await openRevision(requested);}catch{notice='';error='revision_unavailable';}}
   const step=$routePage.url.searchParams.get('step');
   if(step&&workspaceSteps.includes(step as typeof workspaceSteps[number]))activeStep=step;
   const position=Number($routePage.url.searchParams.get('position'));
   if(Number.isFinite(position)&&position>0&&position<=1000000){await tick();window.scrollTo({top:position,behavior:'instant'});}
  });
  const warn=(event:BeforeUnloadEvent)=>{if(unsaved){event.preventDefault();event.returnValue='';}};
  window.addEventListener('beforeunload',warn);

  const timer = setInterval(() => { if (active?.state === 'processing' && order===null && !busy && !uploading && document.visibilityState === 'visible') refresh().catch(() => { error = "refresh_failed"; }); }, 2500);
  return () => { window.removeEventListener('beforeunload',warn);clearInterval(timer); queue?.cancel(); };
 });
 async function resumeUpload(){
  if(!active||!pendingSources.length||uploading)return;
  uploading=true;error='';queue=new UploadQueue(gateway);
  try{await queue.run(active,pendingSources,(name,count,total,fraction)=>{progress=(count+fraction)/total;progressText=`${count}/${total}: ${name}`;});pendingSources=[];await refresh();notice=active?.state==='ready'?'':'upload_received';}
  catch(failure){error=failureCode(failure);await refresh().catch(()=>{});}
  finally{uploading=false;}
 }
 async function upload(event:Event){
  const input=event.currentTarget as HTMLInputElement;
  const files=Array.from(input.files||[]);input.value='';
  if(!active||!files.length||uploading)return;
  if(busy)return;busy=true;try{pendingSources=await gateway.prepare(files);await resumeUpload();}catch(failure){error=failureCode(failure);}finally{busy=false;}
 }
 async function saveAttribution(){if(!active)return;await gateway.attribution(active.id,attributionVersion,source,credits,confirmed,preparationMethod,humanReviewed);await refresh();attributionVersion=active!.version;notice='saved';}
 async function replaceFile(event:Event,pageId:string){
  const input=event.currentTarget as HTMLInputElement;const file=input.files?.[0];input.value='';if(!file||!active)return;replacementCapacity=false;if(active.pages.length>=300||active.pages.reduce((total,page)=>total+page.bytes,0)+file.size>500*1024*1024){replacementCapacity=true;return;}
  await run(async()=>{const [source]=await gateway.prepare([file]);active=await replacePage(gateway,active!,pageId,source,()=>{});syncAttribution(active);await refresh();notice='saved';});
 }

 async function prepareShare(){if(!active)return;shareCopied=false;shareText=`${active.titleName} · ${text($locale,active.chapterLabel+'-тарау','Глава '+active.chapterLabel)} · ${active.teamName}\n${window.location.origin}/read/${encodeURIComponent(active.releaseId)}`;try{await navigator.clipboard.writeText(shareText);shareCopied=true;}catch{/* The visible selectable text remains the fallback. */}}
 async function saveOrder(){if(!active||!order)return;await gateway.reorder(active.id,orderVersion,order);order=null;await refresh();notice='saved';}
</script>
<svelte:window onscroll={()=>previewPosition=Math.max(0,Math.round(window.scrollY))}/>
<svelte:head><title>{copy($locale,"Аударма жүктеу — Qmanga")}</title><meta name="robots" content="noindex"/></svelte:head>
<a class="auth-link" href={projectListReturn($routePage.url.searchParams.get('projectsReturn'))}>← {text($locale,'Барлық жобалар','Все проекты')}</a><h1>{project?.titleName||text($locale,'Тарауларды басқару','Управление главами')}</h1>{#if project}<p class="project-meta">{project.teamName} · {editor?text($locale,'Тарауларды қосып, тексеруге жібере аласың','Можешь добавлять главы и отправлять на проверку'):text($locale,'Файлдарды жүктеуге қатысушы рұқсаты','Доступ участника для загрузки файлов')}</p>{/if}
{#if !user}<a class="button primary" href={'/login?returnTo='+encodeURIComponent('/studio/projects/'+projectId)}>{text($locale,'Кіру','Войти')}</a>{:else}
{#if error}<p class="form-message" role="alert">{error==='revision_unavailable'?text($locale,'Сұралған нұсқа қолжетімсіз. Жобаның қолжетімді тарауын не нұсқасын таңда.','Запрошенная версия недоступна. Выбери доступную главу или версию проекта.'):noticeText($locale,error)}</p>{/if}{#if notice}<p class="form-message success" role="status">{noticeText($locale,notice)}</p>{/if}
<div class="workspace-grid editor-workspace">{#if active}<nav class="draft-steps" aria-label={text($locale,"Жариялауға дайындау","Подготовка к публикации")}><a href="#draft-pages" onclick={event=>{event.preventDefault();void showStep('draft-pages');}} aria-current={activeStep==="draft-pages"?"location":undefined}>1. {text($locale,"Файлдар","Файлы")}</a><a href="#draft-details" onclick={event=>{event.preventDefault();void showStep('draft-details');}} aria-current={activeStep==="draft-details"?"location":undefined}>2. {text($locale,"Деректер","Сведения")}</a><a href="#draft-preview" onclick={event=>{event.preventDefault();void showStep('draft-preview');}} aria-current={activeStep==="draft-preview"?"location":undefined}>3. {text($locale,"Тексеру","Проверка")}</a></nav>{/if}<section class="panel draft-panel">{#if active}<button class="button subtle chapter-jump" onclick={showChapterChoice}>{text($locale,'Тарауды таңдау','Выбрать главу')}</button><div class="draft-heading"><h2>{text($locale,active.chapterLabel+"-тарау","Глава "+active.chapterLabel)}</h2><p role="status">{stateNames[active.state] || copy($locale,"Белгісіз")}</p></div><p class="muted">{text($locale,'Оқуға қолжетімділік: ','Доступность для чтения: ')}{active.releaseStatus==='published'?text($locale,'ашық','открыто'):active.releaseStatus==='withdrawn'?text($locale,'оқудан алынған','снято с чтения'):text($locale,'әлі жарияланбаған','ещё не опубликовано')}</p>{#if editor&&canEdit(active.state)}<button class="button subtle discard-trigger" disabled={busy||uploading||pendingSources.length>0||order!==null||attributionDirty} onclick={()=>discardDialog?.showModal()}>{text($locale,'Нобайті жою','Удалить черновик')}</button>{/if}{#if active.releaseStatus==='published'}<div class="actions"><a class="button subtle" href={'/read/'+encodeURIComponent(active.releaseId)}>{text($locale,'Жарияланған тарауды ашу','Открыть опубликованную главу')}</a><button class="button subtle" onclick={prepareShare}>{text($locale,'Анонсты көшіру','Скопировать анонс')}</button></div>{#if shareText}<label>{text($locale,'Бөлісуге дайын мәтін','Текст для публикации')}<textarea readonly value={shareText} rows="3" onclick={event=>event.currentTarget.select()}></textarea></label>{#if shareCopied}<p role="status">{text($locale,'Көшірілді','Скопировано')}</p>{/if}{/if}{/if}{#if active.note}<p class="form-message">{active.note}</p>{/if}
<p class="step-progress" role="status">{text($locale,stepNumber+' / 3-қадам', 'Шаг '+stepNumber+' из 3')}</p><progress class="step-meter" max="3" value={stepNumber} aria-label={text($locale,'Дайындау қадамы','Этап подготовки')}></progress>
<section id="draft-pages" class:step-hidden={activeStep!=='draft-pages'}>{#if canEdit(active.state)}<h3 tabindex="-1">1. {text($locale,"Файлдар мен реті","Файлы и порядок")}</h3><label class="upload-field">{text($locale,"Суреттерді қосу · JPEG, PNG, WebP","Добавить изображения · JPEG, PNG, WebP")}<input type="file" multiple accept="image/jpeg,image/png,image/webp" disabled={busy || uploading || pendingSources.length>0 || order!==null || attributionDirty || pendingSources.length>0} onchange={upload}/></label><p class="muted">{copy($locale,"Файлдар табиғи ретпен жүктеледі. Байланыс үзілсе, сол файлдарды қайта таңдаңыз: дайындары қайталанбайды.")}</p><p class="muted">{text($locale,"25 MiB/файл, 300 бетке дейін. Оқу нұсқалары WebP-ге автоматты өңделеді.","До 25 MiB на файл, до 300 страниц. Варианты для чтения автоматически обрабатываются в WebP.")}</p>{:else}<h3 tabindex="-1">1. {text($locale,"Беттер","Страницы")}</h3>{/if}
{#if active.pages.length>=300||replacementCapacity}<p class="form-message" role="status">{text($locale,'Қауіпсіз ауыстыру үшін бір бос орын және жаңа файлға орын қажет. Шекке жетсең, бастапқы файлды сақтап алып, бетті тек түзету черновигінен жойып, ретті сақта; содан кейін жаңа файлды қос. Жарияланған тарау өзгермейді.','Для безопасной замены нужны один свободный слот и место для нового файла. При достижении лимита сохрани исходный файл, удали страницу только из черновика исправления и сохрани порядок; затем добавь новый файл. Опубликованная глава останется прежней.')}</p>{/if}
{#if uploading}<progress max="1" value={progress}></progress><p class="muted">{progressText}</p><button class="button subtle" onclick={() => queue?.cancel()}>{copy($locale,"Жүктеуді тоқтату")}</button>{/if}
{#if pendingSources.length>0&&!uploading}<div class="actions"><button class="button primary" disabled={busy} onclick={resumeUpload}>{text($locale,'Жүктеуді жалғастыру','Продолжить загрузку')}</button><button class="button subtle" disabled={busy} onclick={()=>pendingSources=[]}>{text($locale,'Кезекті тазарту','Очистить очередь')}</button></div>{/if}
{#if order!==null}<div class="order-notice"><p role="status">{text($locale,'Рет пен жою өзгерістері әлі сақталмады.','Изменения порядка и удаления ещё не сохранены.')}</p><div class="actions"><button class="button primary" disabled={busy||uploading} onclick={()=>run(saveOrder)}>{text($locale,'Ретті сақтау','Сохранить порядок')}</button><button class="button subtle" disabled={busy} onclick={()=>order=null}>{text($locale,'Өзгерістерді қайтару','Отменить изменения')}</button></div></div>{/if}
<section class="processing-summary" aria-label={text($locale,'Беттерді өңдеу','Обработка страниц')}><p role="status">{text($locale,'Дайын','Готово')}: {processing.ready} · {text($locale,'Өңделуде','Обработка')}: {processing.processing} · {text($locale,'Қате','Ошибки')}: {processing.failed}{#if processing.unknown} · {text($locale,'Белгісіз','Неизвестно')}: {processing.unknown}{/if}</p><button class="button subtle" disabled={busy||uploading||order!==null} onclick={()=>run(refresh)}>{text($locale,'Күйін жаңарту','Обновить состояние')}</button>{#if processing.failed}<div class="actions">{#each processing.failedIDs as id}<button class="button subtle" onclick={()=>focusPage(id)}>{text($locale,'Қате бетке өту','К странице с ошибкой')} {active.pages.findIndex(page=>page.id===id)+1}</button>{/each}</div>{/if}</section>
{#if orderedPages.length}<button class="button subtle" aria-pressed={pageOverview} onclick={()=>pageOverview=!pageOverview}>{text($locale,'Беттер торы','Сетка страниц')}</button>{/if}
{#if pageOverview}<nav class="page-overview" aria-label={text($locale,'Беттерге өту','Перейти к странице')}>{#each orderedPages as page,index (page.id)}<button onclick={()=>focusPage(page.id)}>{#if page.thumbnailId}<img src={'/api/v1/media/'+encodeURIComponent(page.thumbnailId)} alt="" loading="lazy"/>{/if}<strong>{index+1}</strong><small>{pageStates[page.status]||text($locale,'Белгісіз','Неизвестно')}</small></button>{/each}</nav>{/if}
<ol>{#each orderedPages as page,index (page.id)}<li id={'studio-page-'+page.id} tabindex="-1"><div class="page-summary">{#if page.thumbnailId}<img class="page-thumbnail" src={'/api/v1/media/'+encodeURIComponent(page.thumbnailId)} alt={text($locale,(index+1)+'-бет','Страница '+(index+1))} loading="lazy"/>{/if}<div><strong>{text($locale,(index+1)+'-бет','Страница '+(index+1))}</strong>{#if page.originalName}<span class="filename">{page.originalName}</span>{/if}<small>{page.width}×{page.height} / {(page.bytes / 1048576).toFixed(2)} MiB / {pageStates[page.status] || copy($locale,"Белгісіз")}</small>{#if page.status==='failed'}<p class="page-error">{text($locale,"Өңдеу сәтсіз. Осы файлды қайта таңда немесе бетті ауыстыр.","Обработка не удалась. Выбери этот файл повторно или замени страницу.")}</p>{#if page.failure==='processing_failed'&&canEdit(active.state)}<button class="button subtle" disabled={busy||uploading||order!==null} onclick={()=>run(async()=>{await gateway.retryPage(active!.id,page.id);await refresh();})}>{text($locale,'Өңдеуді қайталау','Повторить обработку')}</button>{/if}{/if}</div></div>{#if editor&&page.status==='ready'}<a class="button subtle" href={'/studio/projects/'+encodeURIComponent(projectId)+'/metadata?coverPage='+encodeURIComponent(page.id)}>{text($locale,'Мұқаба ретінде ұсыну','Предложить как обложку')}</a>{/if}{#if canEdit(active.state)}<div class="row-actions"><label class="replace-file">{text($locale,'Бетті ауыстыру','Заменить страницу')}<input type="file" accept="image/jpeg,image/png,image/webp" disabled={busy||uploading||pendingSources.length>0||order!==null||attributionDirty} onchange={event=>replaceFile(event,page.id)}/></label><label class="position-label">{text($locale,'Орын','Позиция')}<input type="number" min="1" max={orderedPages.length} value={index+1} disabled={busy||uploading} onchange={event=>stageMove(page.id,Number(event.currentTarget.value))}/></label><button class="button subtle" aria-label={text($locale,page.position+'-бетті жоғары жылжыту','Переместить страницу '+page.position+' вверх')} disabled={busy || uploading || index === 0} onclick={() => stageMove(page.id,index)}>↑</button><button class="button subtle" aria-label={text($locale,page.position+'-бетті төмен жылжыту','Переместить страницу '+page.position+' вниз')} disabled={busy || uploading || index === orderedPages.length - 1} onclick={() => stageMove(page.id,index+2)}>↓</button><button class="button subtle" disabled={busy||uploading} onclick={()=>{if(order===null)orderVersion=active!.version;order=(order||active!.pages.map(item=>item.id)).filter(id=>id!==page.id);}}>{copy($locale,"Жою")}</button></div>{/if}</li>{/each}</ol>
<div class="step-actions"><button class="button primary" disabled={busy||uploading||pendingSources.length>0||order!==null||(canEdit(active.state)&&!canSubmit(active))} onclick={()=>showStep('draft-details')}>{text($locale,'Келесі: деректер','Далее: сведения')}</button></div>
{#if canEdit(active.state)&&!canSubmit(active)}<p class="muted">{text($locale,'Беттерді қосып, өңдеудің аяқталуын күт.','Добавь страницы и дождись завершения обработки.')}</p>{/if}</section>
{#if canEdit(active.state)}<form id="draft-details" class:step-hidden={activeStep!=='draft-details'} onsubmit={event=>{event.preventDefault();void run(event.submitter?.getAttribute('name')==='review'?saveAndReview:saveAttribution);}}><fieldset disabled={busy||uploading}>
<h3 tabindex="-1">2. {text($locale,'Деректер мен кредиттер','Сведения и кредиты')}</h3><label>{text($locale,'Дереккөз және жариялау құқығының негізі','Источник и основание права публикации')}<textarea bind:value={source} required minlength="8" maxlength="2000" rows="3"></textarea></label>
<label>{text($locale,'Кредиттер: авторлар мен аудармашылар','Кредиты: авторы и переводчики')}<textarea bind:value={credits} required minlength="2" maxlength="2000" rows="3"></textarea></label>
<label>{text($locale,'Дайындау тәсілі','Способ подготовки')}<select bind:value={preparationMethod}><option value="unspecified">{text($locale,'Көрсетілмеген','Не указан')}</option><option value="manual">{text($locale,'Қолмен','Вручную')}</option><option value="machine_assisted">{text($locale,'Машина көмегімен','С помощью машины')}</option><option value="machine">{text($locale,'Машиналық','Машинный')}</option></select></label><label class="rights-check"><input type="checkbox" bind:checked={humanReviewed}/>{text($locale,'Команда мәтін мен беттерді адам тексергенін растайды','Команда подтверждает, что человек проверил текст и страницы')}</label>
<label class="rights-check"><input type="checkbox" bind:checked={confirmed} required/>{text($locale,'Осы материалды жариялауға құқығым бар екенін растаймын','Подтверждаю наличие права на публикацию этого материала')}</label><p class="muted">{text($locale,'Бұл мәтіндер читалкада көрінеді. Жеке құжаттар мен деректерді жазба.','Эти тексты видны в читалке. Не указывай личные документы и данные.')}</p>
<button class="button subtle" disabled={busy||uploading||order!==null}>{text($locale,'Деректерді сақтау','Сохранить сведения')}</button>{#if attributionDirty}<button type="button" class="button subtle" disabled={busy||uploading} onclick={()=>run(async()=>{await refresh();if(active)syncAttribution(active);})}>{text($locale,'Өзгерістерді қайтару','Отменить изменения')}</button>{/if}{#if active.rightsConfirmed}<p role="status">{text($locale,'Жариялау деректері сақталған','Сведения о публикации сохранены')}</p>{/if}</fieldset><div class="step-actions"><button type="button" class="button subtle" onclick={()=>showStep('draft-pages')}>{text($locale,'Артқа: файлдар','Назад: файлы')}</button><button class="button primary" name="review" disabled={busy||uploading||order!==null}>{text($locale,'Сақтап, тексеру','Сохранить и проверить')}</button></div></form>{:else}<section id="draft-details" class:step-hidden={activeStep!=='draft-details'}><h3 tabindex="-1">2. {text($locale,'Деректер мен кредиттер','Сведения и кредиты')}</h3><dl><dt>{text($locale,'Дереккөз','Источник')}</dt><dd>{active.source||'—'}</dd><dt>{text($locale,'Кредиттер','Кредиты')}</dt><dd>{active.credits||'—'}</dd><dt>{text($locale,'Дайындау тәсілі','Способ подготовки')}</dt><dd>{preparationLabel($locale,active.preparationMethod)}</dd><dt>{text($locale,'Команданың тексеру мәлімдемесі','Заявление команды о проверке')}</dt><dd>{active.humanReviewed?text($locale,'Адам тексерген','Проверено человеком'):text($locale,'Көрсетілмеген','Не заявлено')}{#if active.humanReviewed&&active.humanReviewer} · {active.humanReviewer}{/if}{#if active.humanReviewed&&active.humanReviewedAt} · {new Date(active.humanReviewedAt).toLocaleDateString($locale==='ru'?'ru-RU':'kk-KZ')}{/if}</dd></dl><div class="step-actions"><button class="button subtle" onclick={()=>showStep('draft-pages')}>{text($locale,'Артқа: файлдар','Назад: файлы')}</button><button class="button primary" onclick={()=>showStep('draft-preview')}>{text($locale,'Келесі: тексеру','Далее: проверка')}</button></div></section>{/if}
<section id="draft-preview" class:step-hidden={activeStep!=='draft-preview'}><h3 tabindex="-1">3. {text($locale,"Тексеру және жіберу","Проверка и отправка")}</h3>{#if canEdit(active.state)}<section class="preflight" aria-label={text($locale,'Жіберуге дайындық','Готовность к отправке')}><h4>{text($locale,'Жіберуге дейін','Перед отправкой')}</h4>{#if busy}<p role="status">{text($locale,'Күйі тексерілуде…','Проверяем состояние…')}</p>{:else if error}<p role="status">{text($locale,'Соңғы әрекет орындалмады. Күйді жаңартып, қайта тексер.','Последнее действие не удалось. Обнови состояние и проверь ещё раз.')}</p>{/if}{#if obstacles.length}<ul>{#each obstacles as reason}<li><button class="button subtle" onclick={()=>showStep(reason==='details'?'draft-details':'draft-pages')}>{obstacleLabel(reason)}</button></li>{/each}</ul>{:else if !busy&&!error}<p role="status">{text($locale,'Беттер мен деректер жіберуге дайын','Страницы и сведения готовы к отправке')}</p>{/if}</section>{/if}{#if canEdit(active.state)}<p class="muted">{text($locale,"Өңдеу аяқталып, рет пен деректер сақталған соң, читалкада тексеріп шық. Содан кейін модераторға жібер.","После обработки сохрани порядок и сведения, проверь главу в читалке и отправь модератору.")}</p>{#if attributionDirty}<p role="status">{text($locale,"Деректердегі өзгерістер әлі сақталмады.","Изменения сведений ещё не сохранены.")}</p>{/if}{#if !editor}<p class="muted">{text($locale,"Тексеруге тек редактор не команда иесі жібере алады.","Отправить на проверку может редактор или владелец команды.")}</p>{/if}<div class="actions"><button class="button subtle" disabled={busy||order!==null} onclick={() => run(refresh)}>{copy($locale,"Күйін жаңарту")}</button>{#if active.pages.length&&active.pages.every(page=>page.status==='ready')&&order===null&&!attributionDirty}<a class="button subtle" href={previewHref()}>{copy($locale,"Алдын ала оқу")}</a>{:else}<span class="button subtle" aria-disabled="true">{text($locale,'Алдын ала оқу өңдеуден кейін ашылады','Предпросмотр после обработки и сохранения')}</span>{/if}<button class="button primary" disabled={busy || uploading || (order!==null||attributionDirty||!editor||!canSubmit(active)||!active.rightsConfirmed||obstacles.length>0)} onclick={() => run(async () => { await gateway.submit(active!.id,active!.version); await refresh(); await reload(); notice = "submitted"; })}>{copy($locale,"Тексеруге жіберу")}</button></div>{:else}<p class="muted">{active.state==='submitted'?text($locale,'Тарау модераторда. Шешім осында және хабарларда пайда болады.','Глава у модератора. Решение появится здесь и в уведомлениях.'):text($locale,'Жарияланған нұсқа өзгермейді. Түзету черновигіне беттер мен кредиттер көшіріледі. Тек қажет беттерді өзгерт.','Опубликованная версия сохраняется. Черновик исправления получит копию страниц и кредитов. Измени только нужные страницы.')}</p><div class="actions"><a class="button subtle" href={previewHref()}>{text($locale,'Алдын ала оқу','Предпросмотр')}</a>{#if active.state==='published'||active.state==='changes_requested'}<button class="button primary" disabled={busy||uploading} onclick={()=>run(async()=>{active=await gateway.create(projectId,active!.chapterId);chapterId=active.chapterId;await reload();})}>{text($locale,'Түзетуге нобай ашу','Открыть черновик исправления')}</button>{:else}<a class="button subtle" href="/notifications">{text($locale,'Хабарлар','Уведомления')}</a>{/if}</div>{/if}<div class="step-actions"><button class="button subtle" onclick={()=>showStep('draft-details')}>{text($locale,'Артқа: деректер','Назад: сведения')}</button></div></section>
{:else}<p class="muted">{copy($locale,"Тарауды немесе нұсқаны таңдаңыз.")}</p>{/if}</section><section class="panel chapter-sidebar"><details class="chapter-choice" bind:this={chapterChoice} bind:open={choosingChapter}><summary>{text($locale,'Тарау таңдау немесе қосу','Выбрать или создать главу')}</summary>
<form onsubmit={event=>{event.preventDefault();void run(openDraft);}}>
<label>{text($locale,'Тарау','Глава')}<select bind:value={newChapter} disabled={busy||uploading||pendingSources.length>0||order!==null||attributionDirty}><option value={false}>{text($locale,'Бар тараудан таңдау','Выбрать существующую')}</option>{#if editor}<option value={true}>{text($locale,'Жаңа тарау қосу','Добавить новую главу')}</option>{/if}</select></label>
{#if newChapter&&editor}<label>{text($locale,'Тарау нөмірі немесе атауы','Номер или обозначение главы')}<input bind:value={chapterLabel} required maxlength="64" placeholder="1, 1.5, Special"/></label><label>{text($locale,'Том · міндетті емес','Том · необязательно')}<input bind:value={chapterVolume} maxlength="32"/></label><label>{text($locale,'Тарау атауы · міндетті емес','Название главы · необязательно')}<input bind:value={chapterName} maxlength="200"/></label><details><summary>{text($locale,'Тізімдегі реті','Порядок в списке')}</summary><label>{text($locale,'Бос қалса — соңына қосылады','Пусто — добавить в конец')}<input type="number" bind:value={chapterOrder} min="1" max="1000000"/></label></details>
{:else}<label>{text($locale,'Қолда бар тараулар','Существующие главы')}<select bind:value={chapterId} required><option value="">{text($locale,'Тарауды таңда','Выбери главу')}</option>{#each chapters as chapter}<option value={chapter.id}>{chapter.label} {chapter.name}</option>{/each}</select></label>{/if}
<button class="button primary" disabled={busy||uploading||pendingSources.length>0||order!==null||attributionDirty||(!newChapter&&!chapterId)||(newChapter&&!editor)}>{newChapter?text($locale,'Тарау қосып, нобай ашу','Добавить главу и открыть черновик'):text($locale,'Нобай ашу','Открыть черновик')}</button>
</form></details><p class="muted">{text($locale,'Бар нобай қайта ашылады. Жарияланған тарау түзету кезінде оқуға ашық қалады.','Существующий черновик откроется повторно. Опубликованная глава остаётся доступной во время исправления.')}</p>
{#if moreChapters}<button class="button subtle" disabled={busy} onclick={()=>run(loadMoreChapters)}>{text($locale,'Тағы тараулар','Ещё главы')}</button>{/if}<h3>{text($locale,"Тараулар мен нұсқалар","Главы и версии")}</h3>{#each revisionGroups as group (group.id)}<section class="chapter-group" aria-labelledby={'chapter-group-'+group.id}><h4 id={'chapter-group-'+group.id}>{text($locale,group.label+'-тарау','Глава '+group.label)}{#if group.name}<span>{group.name}</span>{/if}</h4>{#each group.revisions as revision (revision.id)}<button class="revision-option button subtle" aria-current={active?.id===revision.id?'true':undefined} disabled={busy||uploading||pendingSources.length>0||order!==null||attributionDirty||chapterDirty} onclick={()=>run(()=>openRevision(revision.id))}><span class="revision-state">{stateNames[revision.state]||copy($locale,"Белгісіз")}{#if active?.id===revision.id}<strong class="opened-version">✓ {text($locale,'Ашық','Открыта')}</strong>{/if}</span>{#if active?.id===revision.id}<small>{text($locale,'Беттер: ','Страниц: ')+active.pages.length}</small>{/if}</button>{/each}</section>{:else}<p class="muted">{copy($locale,"Нұсқа әлі жоқ.")}</p>{/each}{#if moreRevisions}<button class="button subtle" disabled={busy} onclick={()=>run(loadMoreRevisions)}>{text($locale,'Тағы нұсқалар','Ещё версии')}</button>{/if}</section>
</div>{#if editor}<section class="panel cover-panel"><h2>{text($locale,'Тайтл деректері','Данные тайтла')}</h2><p class="muted">{text($locale,'Сипаттама, жанрлар, санаттар, мұқаба және баннер модерация арқылы өзгереді.','Описание, жанры, категории, обложка и баннер меняются через модерацию.')}</p>{#if project?.coverId}<img class="page-thumbnail" src={'/api/v1/media/'+encodeURIComponent(project.coverId)} alt={text($locale,'Қазіргі мұқаба','Текущая обложка')}/>{/if}<a class="button subtle" href={'/studio/projects/'+encodeURIComponent(projectId)+'/metadata'}>{text($locale,'Жоба деректерін өзгерту','Изменить данные проекта')}</a></section>{/if}
{/if}
<dialog bind:this={discardDialog} class="discard-dialog" aria-labelledby="discard-title"><h2 id="discard-title">{text($locale,'Нобайті жою керек пе?','Удалить черновик?')}</h2><p>{text($locale,(active?.chapterLabel||'')+'-тарау · '+(active?.pages.length||0)+' бет жойылады. Жарияланған нұсқа қалса, ол өзгермейді.','Глава '+(active?.chapterLabel||'')+' · будет удалено страниц: '+(active?.pages.length||0)+'. Опубликованная версия останется доступной.')}</p>{#if error}<p class="form-message" role="alert">{noticeText($locale,error)}</p>{/if}<div class="actions"><button class="button subtle" type="button" onclick={()=>discardDialog?.close()}>{text($locale,'Бас тарту','Отмена')}</button><button class="button primary" type="button" disabled={busy} onclick={()=>run(discardDraft)}>{text($locale,'Нобайті жою','Удалить черновик')}</button></div></dialog>
<style>.processing-summary,.preflight{margin-block:16px;padding-block:12px;border-block:1px solid var(--line)}.preflight h4{margin:0}.preflight ul{list-style:none;padding:0}.preflight li{padding:0;border:0;background:none}.preflight button{white-space:normal;text-align:start}.page-overview{display:grid;grid-template-columns:repeat(auto-fill,minmax(80px,1fr));gap:8px;margin-block:16px}.page-overview button{min-height:44px;min-width:0;padding:8px;background:var(--bg);color:var(--text);border:1px solid var(--line);border-radius:8px}.page-overview img{display:block;width:100%;height:100px;object-fit:contain;margin-bottom:6px}.page-overview small{overflow-wrap:anywhere}li:focus{outline:2px solid var(--accent);outline-offset:2px}.chapter-group{margin-top:20px}.chapter-group h4{font-size:15px;margin:0 0 8px;overflow-wrap:anywhere}.chapter-group h4 span{display:block;font-weight:400;color:var(--muted);font-size:13px;margin-top:4px}.revision-state{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;width:100%;overflow-wrap:anywhere}.opened-version{font-size:12px}.revision-option[aria-current]{border-color:var(--accent);border-inline-start-width:3px}.revision-option{flex-direction:column;align-items:flex-start;gap:4px;min-height:44px}.chapter-jump{min-height:44px;margin-bottom:12px}.chapter-choice{scroll-margin-top:80px}.cover-panel{margin-top:24px}.step-hidden{display:none}@media(min-width:1000px){.step-hidden{display:block}}.step-progress{color:var(--muted);font-size:13px;margin:12px 0 6px}.step-meter{height:4px;accent-color:var(--accent);margin-bottom:16px;border:0;border-radius:2px;overflow:hidden;background:var(--line)}.step-meter::-webkit-progress-bar{background:var(--line)}.step-meter::-webkit-progress-value{background:var(--accent)}.step-meter::-moz-progress-bar{background:var(--accent)}.step-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:20px}.step-actions .button{min-height:44px}.chapter-choice>summary{font-weight:700;font-size:17px}.draft-panel h3:focus{outline:2px solid var(--accent);outline-offset:4px}fieldset{border:0;padding:0;margin:0;min-width:0}.page-summary{display:flex;gap:12px;min-width:0}.page-summary>div{min-width:0}.page-thumbnail{width:64px;height:88px;object-fit:cover;object-position:top;border:1px solid var(--line);flex:none}.filename{display:block;overflow-wrap:anywhere;font-size:14px;margin:4px 0}dt{font-size:13px;color:var(--muted)}dd{margin:8px 0 16px;white-space:pre-wrap;overflow-wrap:anywhere}.editor-workspace{grid-template-columns:minmax(0,1fr)}.chapter-sidebar{align-self:start}.project-meta{color:var(--muted);font-size:14px;margin:8px 0 24px}.draft-heading{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.draft-heading p{font-size:14px}.discard-trigger{margin:6px 0 12px}.discard-dialog{width:min(420px,calc(100vw - 32px));padding:24px;border:1px solid var(--line);border-radius:12px;background:var(--panel);color:var(--text);box-shadow:0 24px 72px #0008}.discard-dialog::backdrop{background:#0009}.discard-dialog h2{margin:0 0 12px;font-size:20px}.discard-dialog p{line-height:1.5}.discard-dialog .actions{justify-content:flex-end}.draft-steps{display:flex;gap:4px;min-width:0;overflow-x:auto;border-bottom:1px solid var(--line);margin:0;padding:4px 0 8px}.draft-steps a{display:flex;align-items:center;min-height:44px;padding:8px 10px;white-space:nowrap;font-size:13px;text-decoration:none;color:var(--muted);border-radius:6px}.draft-steps a[aria-current]{background:var(--raised);color:var(--accent);font-weight:700}.upload-field{border:1px dashed var(--line);padding:16px}.draft-panel h3{font-size:17px;margin:24px 0 12px;scroll-margin-top:80px}#draft-details,#draft-preview{border-top:1px solid var(--line);margin-top:28px;padding-top:12px;scroll-margin-top:80px}.page-error{font-size:14px;margin:8px 0}.chapter-sidebar form{display:grid;gap:12px}.chapter-sidebar .button{justify-self:start}summary{min-height:44px;display:flex;align-items:center;cursor:pointer;font-size:14px}@media(min-width:1000px){.editor-workspace{grid-template-columns:250px minmax(0,1fr) 150px;gap:16px}.chapter-sidebar{grid-column:1;grid-row:1}.draft-panel{grid-column:2;grid-row:1}.draft-steps{grid-column:3;grid-row:1;display:grid;align-self:start;position:sticky;top:88px;overflow:visible;border-bottom:0;border-left:1px solid var(--line);padding:0 0 0 12px}.draft-steps a{position:relative;white-space:normal}.draft-steps a[aria-current]::before{content:"";position:absolute;left:-13px;top:6px;bottom:6px;width:3px;background:var(--accent);border-radius:3px}}.replace-file{max-width:240px;min-width:0}.replace-file input{max-width:100%}.position-label{max-width:100px;margin:0!important}.row-actions{align-items:end}.order-notice{padding:16px 0;border-block:1px solid var(--line)}.rights-check{display:flex;align-items:center;gap:12px;min-height:44px}.rights-check input{width:20px;min-height:20px;height:20px}.revision-option { width:100%; justify-content:flex-start; margin:5px 0; } ol { padding:0; list-style:none; } li { border:1px solid var(--line);border-radius:10px;background:var(--bg);margin-block:10px; padding:14px; display:grid; gap:8px; } small { display:block; color:var(--muted); } .row-actions,.actions { display:flex; gap:8px; flex-wrap:wrap; } .actions { margin-top:20px; } progress { width:100%; } .panel label { margin:16px 0; } h1 { overflow-wrap:anywhere; }</style>
